export const PROGRAM_NAME = 'test16_executable';
export const DESCRIPTION = 'Large scale markdown processing';
export const REFERENCE_EXECUTABLE_PATH = '/workspace/dataset/test16_executable';

export const REQUIRED_KEYS = Object.freeze(['a', 'b', 'c', 'd', 'e']);

export const KEY_BY_LONG_OPTION = new Map([
  ['--a', 'a'],
  ['--b', 'b'],
  ['--c', 'c'],
  ['--d', 'd'],
  ['--e', 'e'],
]);

export const CANONICAL_OPTIONS = Object.freeze([
  ['a', '--a'],
  ['b', '--b'],
  ['c', '--c'],
  ['d', '--d'],
  ['e', '--e'],
]);

export const USAGE_TEXT = `usage: ${PROGRAM_NAME} [-h] --a A --b B --c C --d D --e E\n`;

export const HELP_TEXT =
  `${USAGE_TEXT}\n` +
  `${DESCRIPTION}\n\n` +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n' +
  '  --b B\n' +
  '  --c C\n' +
  '  --d D\n' +
  '  --e E\n';

export function buildCanonicalArgv(values) {
  const argv = [];

  for (const [key, option] of CANONICAL_OPTIONS) {
    argv.push(option, values[key]);
  }

  return argv;
}

