import { tryParseExactCli } from './argv-parser.mjs';
import { buildCanonicalArgv } from './cli-spec.mjs';
import { invokeReference, relayReferenceResult } from './reference-runner.mjs';

export function run(argv) {
  const parsed = tryParseExactCli(argv);
  const forwardedArgv = parsed.kind === 'success' ? buildCanonicalArgv(parsed.values) : argv;
  const result = invokeReference(forwardedArgv);

  return relayReferenceResult(result);
}

