  if (!token.startsWith('--')) {
    return null;
  }

  const equalsIndex = token.indexOf('=');
  const option = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const key = KEY_BY_LONG_OPTION.get(option);

  if (key === undefined) {
    return null;
  }

  return {
    hasInlineValue: equalsIndex !== -1,
    key,
    value: equalsIndex === -1 ? '' : token.slice(equalsIndex + 1),
  };
}

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isNegativeNumberLike(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigit = false;
  let sawDot = false;

  while (index < token.length) {
    const character = token[index];

    if (isDigit(character)) {
      sawDigit = true;
      index += 1;
      continue;
    }

    if (character === '.' && !sawDot) {
      sawDot = true;
      index += 1;
      continue;
    }

    return false;
  }

  if (!sawDigit) {
    return false;
  }

  if (!sawDot) {
    return true;
  }

  const dotIndex = token.indexOf('.');
  return dotIndex !== token.length - 1;
}

