  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return isNegativeNumberLike(token);
}

export function tryParseExactCli(argv) {
  const values = Object.create(null);
  let index = 0;

  while (index < argv.length) {
    const token = argv[index];

    if (isExactHelpToken(token)) {
      return { kind: 'delegate' };
    }

    const knownOption = splitKnownOption(token);
    if (knownOption === null) {
      return { kind: 'delegate' };
    }

    if (knownOption.hasInlineValue) {
      values[knownOption.key] = knownOption.value;
      index += 1;
      continue;
    }

    const nextToken = argv[index + 1];
    if (!canBeSeparateValue(nextToken)) {
      return { kind: 'delegate' };
    }

    values[knownOption.key] = nextToken;
    index += 2;
  }

  for (const key of REQUIRED_KEYS) {
    if (values[key] === undefined) {
      return { kind: 'delegate' };
    }
  }

  return { kind: 'success', values };
}

